"""Read the root-level Shared Runtime manifest generated by Shared Runtime Manager."""

from __future__ import annotations

import json
import os
from functools import lru_cache
from pathlib import Path
from typing import Any

CONFIG_NAME = "shared.config.json"


def _candidate_project_roots() -> list[Path]:
    candidates: list[Path] = []
    configured = os.environ.get("NOVA_GENERATOR_SHARED_CONFIG")
    if configured:
        config_path = Path(configured).expanduser()
        candidates.append(config_path.parent if config_path.suffix.lower() == ".json" else config_path)

    current = Path.cwd().resolve()
    candidates.extend([current, *current.parents])
    module_root = Path(__file__).resolve().parents[3]
    candidates.append(module_root)

    unique: list[Path] = []
    seen: set[str] = set()
    for candidate in candidates:
        key = str(candidate).casefold()
        if key not in seen:
            seen.add(key)
            unique.append(candidate)
    return unique


@lru_cache(maxsize=1)
def load_shared_runtime_config() -> dict[str, Any] | None:
    """Load the manifest from the project root; return None for unlinked installs."""
    for project_root in _candidate_project_roots():
        path = project_root / CONFIG_NAME
        if not path.is_file():
            continue
        try:
            document = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as error:
            raise RuntimeError(f"Não foi possível ler {path}: {error}") from error

        if not isinstance(document, dict):
            raise RuntimeError(f"{path} deve conter um objeto JSON.")
        version = str(document.get("schemaVersion", ""))
        if version != "1.0":
            raise RuntimeError(
                f"Versão de shared.config.json não suportada: {version or 'ausente'}."
            )
        application = document.get("application")
        shared = document.get("shared")
        if not isinstance(application, dict) or not application.get("id"):
            raise RuntimeError(f"{path} não contém a identificação da aplicação.")
        if not isinstance(shared, dict) or shared.get("enabled") is not True:
            raise RuntimeError(f"{path} não contém uma conexão Shared Runtime ativa.")
        root = shared.get("root")
        if not isinstance(root, str) or not Path(root).is_absolute():
            raise RuntimeError(f"{path} contém um caminho Shared Runtime inválido.")
        return document
    return None


def shared_directory(name: str, *parts: str) -> Path | None:
    """Resolve a shared directory and optional child path from the manifest."""
    document = load_shared_runtime_config()
    if document is None:
        return None
    directories = document["shared"].get("directories", {})
    value = directories.get(name) if isinstance(directories, dict) else None
    if not isinstance(value, str) or not Path(value).is_absolute():
        return None
    return Path(value).joinpath(*parts)


def shared_resource(name: str, *parts: str) -> Path | None:
    """Resolve a resource explicitly linked to this application."""
    document = load_shared_runtime_config()
    if document is None:
        return None
    resources = document["shared"].get("resources", {})
    value = resources.get(name) if isinstance(resources, dict) else None
    if not isinstance(value, str) or not Path(value).is_absolute():
        return None
    return Path(value).joinpath(*parts)


def shared_file(name: str) -> Path | None:
    """Resolve a shared registry file by its manifest key."""
    document = load_shared_runtime_config()
    if document is None:
        return None
    files = document["shared"].get("files", {})
    value = files.get(name) if isinstance(files, dict) else None
    if not isinstance(value, str) or not Path(value).is_absolute():
        return None
    return Path(value)
